import{_ as n,C as s,o as i,c as r,j as t,a as o,G as d,a3 as l}from"./chunks/framework.B6x8LOwa.js";const f=JSON.parse('{"title":"Smart Ink Processing","description":"Intelligent line straightening, shape recognition, endpoint snapping, and brush tools in ICC-CE","frontmatter":{"title":"Smart Ink Processing","description":"Intelligent line straightening, shape recognition, endpoint snapping, and brush tools in ICC-CE"},"headers":[],"relativePath":"en/guide/smart-ink-processing.md","filePath":"en/guide/smart-ink-processing.md"}'),g={name:"en/guide/smart-ink-processing.md"};function h(c,e,p,m,u,b){const a=s("ArticleMetadata");return i(),r("div",null,[e[0]||(e[0]=t("h1",{id:"smart-ink-processing",tabindex:"-1"},[o("Smart Ink Processing "),t("a",{class:"header-anchor",href:"#smart-ink-processing","aria-label":'Permalink to "Smart Ink Processing"'},"​")],-1)),d(a),e[1]||(e[1]=l('<p>ICC-CE provides advanced ink rendering and hand-drawing assistance features that automatically smooth, straighten, and optimize shapes while drawing or writing.</p><h2 id="smart-drawing-assistance" tabindex="-1">Smart Drawing Assistance <a class="header-anchor" href="#smart-drawing-assistance" aria-label="Permalink to &quot;Smart Drawing Assistance&quot;">​</a></h2><h3 id="line-straightening" tabindex="-1">Line Straightening <a class="header-anchor" href="#line-straightening" aria-label="Permalink to &quot;Line Straightening&quot;">​</a></h3><p>When drawing strokes close to a straight line, ICC-CE automatically recognizes and converts them into perfect straight lines. You can adjust sensitivity and threshold in settings:</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th><th>Range</th></tr></thead><tbody><tr><td><strong>Sensitivity</strong></td><td>Controls the threshold for determining stroke straightness</td><td>0.05 - 2.0</td></tr><tr><td><strong>Length Threshold</strong></td><td>Only strokes exceeding the specified length will be straightened</td><td>Adjustable pixels</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Recommendation</p><p>When drawing geometric diagrams or aligned annotation lines, increasing sensitivity helps achieve cleaner results.</p></div><h3 id="shape-recognition" tabindex="-1">Shape Recognition <a class="header-anchor" href="#shape-recognition" aria-label="Permalink to &quot;Shape Recognition&quot;">​</a></h3><p>Automatically recognizes and optimizes hand-drawn shapes into standard geometry:</p><ul><li><strong>Rectangles &amp; Squares</strong></li><li><strong>Triangles</strong></li><li><strong>Circles &amp; Ellipses</strong></li></ul><h3 id="endpoint-snapping" tabindex="-1">Endpoint Snapping <a class="header-anchor" href="#endpoint-snapping" aria-label="Permalink to &quot;Endpoint Snapping&quot;">​</a></h3><p>Endpoints automatically snap to nearby endpoints while drawing, making it easy to create well-connected geometric shapes.</p><hr><h2 id="diverse-drawing-tools" tabindex="-1">Diverse Drawing Tools <a class="header-anchor" href="#diverse-drawing-tools" aria-label="Permalink to &quot;Diverse Drawing Tools&quot;">​</a></h2><h3 id="pens-and-highlighters" tabindex="-1">Pens and Highlighters <a class="header-anchor" href="#pens-and-highlighters" aria-label="Permalink to &quot;Pens and Highlighters&quot;">​</a></h3><ul><li><strong>Thickness &amp; Transparency</strong>: Supports dynamic adjustments of pen size and opacity</li><li><strong>Color Presets</strong>: Built-in color palettes for quick selection</li><li><strong>Pressure Sensitivity</strong>: Automatically responds to writing pressure on supported touch pens or tablets</li></ul><h3 id="touch-modes" tabindex="-1">Touch Modes <a class="header-anchor" href="#touch-modes" aria-label="Permalink to &quot;Touch Modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Feature</th></tr></thead><tbody><tr><td><strong>Fingertip Drawing</strong></td><td>Optimized for standard touchscreens, allowing direct finger drawing</td></tr><tr><td><strong>Pen Mode</strong></td><td>Precision drawing mode designed for active styluses with palm rejection</td></tr><tr><td><strong>Simulated Pressure</strong></td><td>Dynamically simulates pressure variations based on stroke speed on non-pressure devices</td></tr></tbody></table><h3 id="eraser-tools" tabindex="-1">Eraser Tools <a class="header-anchor" href="#eraser-tools" aria-label="Permalink to &quot;Eraser Tools&quot;">​</a></h3><ul><li><strong>Point Eraser</strong>: Precisely erases specific parts of a stroke</li><li><strong>Stroke Eraser</strong>: Removes the entire stroke with a single tap</li><li><strong>Eraser Size &amp; Shape</strong>: Adjustable erasing radius and target shape</li></ul>',19))])}const P=n(g,[["render",h]]);export{f as __pageData,P as default};
